-- =============================================================
-- 供应商准入与绩效评价管理系统 · 数据库初始化脚本
-- MySQL 8 / utf8mb4 / 库名 new_005
-- 执行：mysql -uroot -p123456 < sql/init.sql
-- 默认管理员：admin / admin123
-- 其他账号统一密码：123456
-- =============================================================
SET NAMES utf8mb4;
DROP DATABASE IF EXISTS new_005;
CREATE DATABASE new_005 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE new_005;

-- ---------- 组织 ----------
CREATE TABLE sys_org (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  org_name VARCHAR(60) NOT NULL COMMENT '组织名称',
  parent_id BIGINT DEFAULT 0 COMMENT '上级组织',
  sort INT DEFAULT 0
) ENGINE=InnoDB COMMENT='组织';

-- ---------- 用户 ----------
CREATE TABLE sys_user (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  username VARCHAR(50) NOT NULL COMMENT '登录账号',
  password VARCHAR(100) NOT NULL COMMENT 'BCrypt 密码',
  real_name VARCHAR(50) NOT NULL,
  phone VARCHAR(20),
  email VARCHAR(80),
  avatar VARCHAR(200) COMMENT '头像相对路径',
  org_id BIGINT COMMENT '所属组织',
  supplier_id BIGINT COMMENT '供应商联系人所属企业',
  status TINYINT DEFAULT 1 COMMENT '1 启用 0 停用',
  login_fail_count INT DEFAULT 0 COMMENT '连续失败次数',
  lock_until DATETIME NULL COMMENT '锁定截止时间',
  last_login DATETIME NULL,
  create_time DATETIME,
  update_time DATETIME,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_username (username),
  KEY idx_supplier (supplier_id)
) ENGINE=InnoDB COMMENT='系统用户';

CREATE TABLE sys_role (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  role_code VARCHAR(30) NOT NULL,
  role_name VARCHAR(50) NOT NULL,
  data_scope VARCHAR(20) NOT NULL COMMENT 'all/dept/deptAndChild/self',
  remark VARCHAR(200),
  create_time DATETIME,
  UNIQUE KEY uk_role_code (role_code)
) ENGINE=InnoDB COMMENT='角色';

CREATE TABLE sys_user_role (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  user_id BIGINT NOT NULL,
  role_id BIGINT NOT NULL,
  KEY idx_user (user_id)
) ENGINE=InnoDB COMMENT='用户角色';

CREATE TABLE sys_menu (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  parent_id BIGINT DEFAULT 0,
  menu_name VARCHAR(50) NOT NULL,
  path VARCHAR(100),
  component VARCHAR(100),
  icon VARCHAR(40),
  type VARCHAR(10) DEFAULT 'menu' COMMENT 'menu/button',
  perms VARCHAR(80),
  sort INT DEFAULT 0,
  visible TINYINT DEFAULT 1 COMMENT '0 不在侧栏展示'
) ENGINE=InnoDB COMMENT='菜单';

CREATE TABLE sys_role_menu (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  role_id BIGINT NOT NULL,
  menu_id BIGINT NOT NULL,
  KEY idx_role (role_id)
) ENGINE=InnoDB COMMENT='角色菜单';

CREATE TABLE sys_dict (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  dict_type VARCHAR(40) NOT NULL,
  dict_code VARCHAR(40) NOT NULL,
  dict_label VARCHAR(60) NOT NULL,
  sort INT DEFAULT 0,
  status TINYINT DEFAULT 1,
  KEY idx_type (dict_type)
) ENGINE=InnoDB COMMENT='字典';

CREATE TABLE sys_message (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  user_id BIGINT NOT NULL,
  title VARCHAR(100),
  content VARCHAR(300),
  biz_no VARCHAR(50) COMMENT '业务编号',
  biz_type VARCHAR(30),
  url VARCHAR(200) COMMENT '详情跳转地址',
  read_flag TINYINT DEFAULT 0,
  create_time DATETIME
) ENGINE=InnoDB COMMENT='站内消息';

CREATE TABLE sys_log (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  user_id BIGINT,
  username VARCHAR(50),
  module VARCHAR(30),
  action VARCHAR(40),
  biz_no VARCHAR(50),
  detail VARCHAR(500),
  ip VARCHAR(40),
  cost_ms INT DEFAULT 0,
  create_time DATETIME,
  KEY idx_biz (biz_no)
) ENGINE=InnoDB COMMENT='操作日志';

-- ---------- 业务主数据 ----------
CREATE TABLE supplier_category (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  category_code VARCHAR(20) NOT NULL,
  category_name VARCHAR(50) NOT NULL,
  required_cert VARCHAR(200) COMMENT '该类目必填证照，逗号分隔',
  sort INT DEFAULT 0,
  status TINYINT DEFAULT 1,
  create_time DATETIME,
  UNIQUE KEY uk_category_code (category_code)
) ENGINE=InnoDB COMMENT='供货类目';

CREATE TABLE supplier (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  supplier_code VARCHAR(50) NOT NULL COMMENT '供应商编码',
  supplier_name VARCHAR(120) NOT NULL,
  credit_code VARCHAR(30) NOT NULL COMMENT '统一信用代码',
  category_id BIGINT COMMENT '主供货类目',
  contact_name VARCHAR(50),
  contact_phone VARCHAR(20),
  email VARCHAR(80),
  address VARCHAR(200),
  supplier_status VARCHAR(20) NOT NULL DEFAULT '潜在' COMMENT '潜在/合格/暂停/限期整改/黑名单/已退出',
  level VARCHAR(2) COMMENT 'A/B/C/D',
  risk_level VARCHAR(10) COMMENT '低/中/高',
  admission_date DATE COMMENT '准入日期',
  cert_expire_date DATE COMMENT '最早证照到期日',
  annual_capacity VARCHAR(60),
  main_customers VARCHAR(200),
  capacity_desc VARCHAR(500),
  cover_image VARCHAR(200) COMMENT '厂区照片相对路径',
  owner_id BIGINT COMMENT '责任人',
  org_id BIGINT,
  version INT DEFAULT 1 COMMENT '乐观锁版本号',
  create_time DATETIME,
  update_time DATETIME,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_supplier_code (supplier_code),
  UNIQUE KEY uk_credit_code (credit_code),
  KEY idx_status (supplier_status),
  KEY idx_category (category_id),
  KEY idx_cert_expire (cert_expire_date)
) ENGINE=InnoDB COMMENT='供应商主档';

CREATE TABLE supplier_certificate (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  supplier_id BIGINT NOT NULL,
  cert_type VARCHAR(60) NOT NULL,
  cert_no VARCHAR(80),
  file_path VARCHAR(200) NOT NULL COMMENT '证照附件相对路径',
  issue_date DATE,
  expire_date DATE,
  cert_status VARCHAR(20) DEFAULT '有效' COMMENT '有效/已过期/已作废',
  version_no INT DEFAULT 1 COMMENT '换证版本号',
  remark VARCHAR(200),
  uploader_id BIGINT,
  create_time DATETIME,
  update_time DATETIME,
  KEY idx_supplier (supplier_id),
  KEY idx_expire (expire_date),
  KEY idx_status (cert_status)
) ENGINE=InnoDB COMMENT='供应商证照';

CREATE TABLE admission_application (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  application_no VARCHAR(50) NOT NULL,
  supplier_id BIGINT,
  supplier_name VARCHAR(120) NOT NULL,
  credit_code VARCHAR(30) NOT NULL,
  category_id BIGINT,
  contact_name VARCHAR(50),
  contact_phone VARCHAR(20),
  address VARCHAR(200),
  annual_capacity VARCHAR(60),
  main_customers VARCHAR(200),
  capacity_desc VARCHAR(500),
  status VARCHAR(20) NOT NULL COMMENT '待提交/准入审核/现场评估/待审批/已准入/已驳回/合作评价/分级调整',
  current_node VARCHAR(60),
  submit_time DATETIME,
  deadline DATETIME,
  reviewer_id BIGINT,
  approver_id BIGINT,
  reject_reason VARCHAR(300),
  remark VARCHAR(300),
  version INT DEFAULT 1,
  create_time DATETIME,
  update_time DATETIME,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_application_no (application_no),
  KEY idx_status (status),
  KEY idx_supplier (supplier_id),
  KEY idx_submit (submit_time)
) ENGINE=InnoDB COMMENT='准入申请';

CREATE TABLE review_score (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  application_id BIGINT NOT NULL,
  reviewer_id BIGINT,
  reviewer_name VARCHAR(50),
  quality_score DECIMAL(5,1) COMMENT '质量 30%',
  tech_score DECIMAL(5,1) COMMENT '技术 25%',
  delivery_score DECIMAL(5,1) COMMENT '交付 20%',
  price_score DECIMAL(5,1) COMMENT '价格 15%',
  service_score DECIMAL(5,1) COMMENT '服务 10%',
  total_score DECIMAL(5,1),
  conclusion VARCHAR(30),
  comment VARCHAR(500),
  status VARCHAR(10) DEFAULT '已提交' COMMENT '草稿/已提交',
  create_time DATETIME,
  update_time DATETIME,
  KEY idx_application (application_id)
) ENGINE=InnoDB COMMENT='专业评审评分';

CREATE TABLE performance_task (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  task_no VARCHAR(50) NOT NULL,
  supplier_id BIGINT NOT NULL,
  period_type VARCHAR(10) COMMENT '月度/季度/年度',
  period VARCHAR(20) COMMENT '如 2026 Q3',
  status VARCHAR(20) DEFAULT '待评分' COMMENT '待评分/评分中/已发布/已作废',
  start_date DATE,
  end_date DATE,
  deadline DATE,
  owner_id BIGINT,
  avg_score DECIMAL(5,1),
  final_level VARCHAR(2),
  published_time DATETIME,
  remark VARCHAR(300),
  create_time DATETIME,
  update_time DATETIME,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_task_no (task_no),
  KEY idx_supplier (supplier_id),
  KEY idx_status (status)
) ENGINE=InnoDB COMMENT='绩效评价任务';

CREATE TABLE performance_score (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  task_id BIGINT NOT NULL,
  reviewer_id BIGINT,
  reviewer_name VARCHAR(50),
  quality_score DECIMAL(5,1) COMMENT '质量 30%',
  delivery_score DECIMAL(5,1) COMMENT '交付 25%',
  price_score DECIMAL(5,1) COMMENT '价格 15%',
  response_score DECIMAL(5,1) COMMENT '服务响应 20%',
  complaint_score DECIMAL(5,1) COMMENT '投诉 10%',
  total_score DECIMAL(5,1),
  comment VARCHAR(500),
  status VARCHAR(10) DEFAULT '已提交',
  create_time DATETIME,
  update_time DATETIME,
  KEY idx_task (task_id)
) ENGINE=InnoDB COMMENT='绩效评分明细';

CREATE TABLE supplier_rectification (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  rectification_no VARCHAR(50) NOT NULL,
  supplier_id BIGINT NOT NULL,
  task_id BIGINT,
  source VARCHAR(30) COMMENT '绩效评价/证照过期/现场评审/投诉',
  issue_desc VARCHAR(400),
  measure VARCHAR(400),
  deadline DATE,
  status VARCHAR(20) DEFAULT '待提交措施' COMMENT '待提交措施/待验证/已关闭/已逾期/已转黑名单',
  verify_comment VARCHAR(300),
  verify_by BIGINT,
  verify_time DATETIME,
  create_time DATETIME,
  update_time DATETIME,
  deleted TINYINT DEFAULT 0,
  UNIQUE KEY uk_rect_no (rectification_no),
  KEY idx_supplier (supplier_id),
  KEY idx_status (status)
) ENGINE=InnoDB COMMENT='整改任务';

CREATE TABLE supplier_rule (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  rule_code VARCHAR(30) NOT NULL,
  rule_name VARCHAR(80),
  version VARCHAR(20) NOT NULL COMMENT '规则版本，如 R2026.3',
  status VARCHAR(10) DEFAULT '启用',
  effect_time DATETIME,
  weight_delivery DECIMAL(5,1) COMMENT '交付及时率权重',
  weight_quality DECIMAL(5,1),
  weight_price DECIMAL(5,1),
  weight_response DECIMAL(5,1),
  weight_complaint DECIMAL(5,1),
  weight_cert DECIMAL(5,1),
  threshold_a DECIMAL(5,1),
  threshold_b DECIMAL(5,1),
  threshold_c DECIMAL(5,1),
  create_time DATETIME,
  UNIQUE KEY uk_version (version)
) ENGINE=InnoDB COMMENT='分层模型规则';

CREATE TABLE supplier_snapshot (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  supplier_id BIGINT NOT NULL,
  rule_id BIGINT,
  rule_version VARCHAR(20),
  period VARCHAR(20),
  input_json TEXT COMMENT '输入快照',
  delivery_score DECIMAL(5,1),
  quality_score DECIMAL(5,1),
  price_score DECIMAL(5,1),
  response_score DECIMAL(5,1),
  complaint_score DECIMAL(5,1),
  cert_score DECIMAL(5,1),
  total_score DECIMAL(5,1),
  result_level VARCHAR(2),
  final_level VARCHAR(2),
  adjust_reason VARCHAR(300),
  adjust_by BIGINT,
  adjust_time DATETIME,
  explain_json TEXT COMMENT '结果解释',
  create_time DATETIME,
  KEY idx_supplier (supplier_id),
  KEY idx_period (period)
) ENGINE=InnoDB COMMENT='分层模型计算快照';













